package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import com.fasterxml.jackson.databind.*;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import javax.sql.DataSource;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real accepted test commands; no worker/OSS/HTTP or notification is started. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresAssetExportRepositoryIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002",ROUTE="POST /integration/asset-export-accept";
    static HikariDataSource pool;static PostgresPlatformRepository platform;static PostgresAssetExportRepository exports;static ObjectMapper mapper;static String admin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(5);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().findAndRegisterModules().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);exports=new PostgresAssetExportRepository(pool,platform);admin=actor("padmin");}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static AssetExportJobRepository.Access access(String who){return new AssetExportJobRepository.Access(who,TENANT,platform.membership(who,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Filters filter(){return new Filters(null,null,"", "SYNTHETIC_EXPORT_"+UUID.randomUUID());}
    static String hash(AssetExportJobRepository.Access a,Filters f){String role=platform.membership(a.actorId(),a.tenantId()).orElseThrow().role();return new Command(new AssetExportJobState.Access(UUID.fromString(a.tenantId()),UUID.fromString(a.actorId()),a.permissionVersion(),role,true),f).fingerprint();}
    static Job accept(AssetExportJobRepository.Access a,Filters f,String key){return mapper.convertValue(platform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,key,hash(a,f),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->exports.accept(a,f)),Job.class);}
    static Job accept(){return accept(access(admin),filter(),UUID.randomUUID().toString());}
    static long count(String table)throws Exception{assertTrue(Set.of("mop_asset_export_job","mop_asset_export_attempt","mop_audit","mop_idempotency").contains(table));try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public."+table)){r.next();return r.getLong(1);}}
    static List<Long> counts()throws Exception{return List.of(count("mop_asset_export_job"),count("mop_asset_export_attempt"),count("mop_audit"),count("mop_idempotency"));}
    @Test void acceptancePersistsOneQueuedCommandAuditAndOriginalReceipt()throws Exception{var before=counts();var a=access(admin);var f=filter();var job=accept(a,f,UUID.randomUUID().toString());assertEquals(State.QUEUED,job.state());assertEquals(0,job.version());assertEquals(f,job.filters());assertEquals(hash(a,f),job.inputSha256());assertEquals("padmin",job.acceptedRole());assertEquals(TENANT,job.tenantId());assertEquals(admin,job.createdBy());assertEquals(List.of(before.get(0)+1,before.get(1),before.get(2)+1,before.get(3)+1),counts());assertEquals(job,exports.get(a,job.id()));}
    @Test void sameOriginalKeyAndBodyRecoversExactReceiptWithoutDuplicateWrites()throws Exception{var a=access(admin);var f=filter();String key=UUID.randomUUID().toString();var first=accept(a,f,key);var before=counts();assertEquals(first,accept(a,f,key));assertEquals(before,counts());}
    @Test void sameKeyWithChangedFiltersConflictsWithoutReplacingFirstJob()throws Exception{var a=access(admin);String key=UUID.randomUUID().toString();var first=accept(a,filter(),key);var before=counts();assertEquals(409,assertThrows(DomainException.class,()->accept(a,filter(),key)).status);assertEquals(before,counts());assertEquals(first,exports.get(a,first.id()));}
    @Test void aFreshRepositoryObjectReadsTheCommittedAcceptance(){var a=access(admin);var first=accept(a,filter(),UUID.randomUUID().toString());var fresh=new PostgresAssetExportRepository(pool,new PostgresPlatformRepository(pool,mapper));assertEquals(first,fresh.get(a,first.id()));assertEquals(List.of(),fresh.readinessProblems());}
    @Test void bothCurrentInternalRolesCanAcceptTheirOwnJobs(){for(String role:List.of("padmin","msp")){var a=access(actor(role));var job=accept(a,filter(),UUID.randomUUID().toString());assertEquals(role,job.acceptedRole());assertEquals(job,exports.get(a,job.id()));}}
    @Test void currentCustomerRolesCannotAcceptReadOrListInternalJobs()throws Exception{var before=counts();for(String role:List.of("viewer","tadmin")){var a=access(actor(role));String key=UUID.randomUUID().toString();assertEquals(403,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,key,"a".repeat(64),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->exports.accept(a,filter()))).status);assertEquals(403,assertThrows(DomainException.class,()->exports.get(a,UUID.randomUUID().toString())).status);assertEquals(403,assertThrows(DomainException.class,()->exports.list(a,15,null,null)).status);}assertEquals(before,counts());}
    @Test void otherCreatorAndForeignTenantGetNotFoundAndCannotEnumerateJob(){var first=accept();var otherCreator=access(actor("msp"));assertEquals(404,assertThrows(DomainException.class,()->exports.get(otherCreator,first.id())).status);assertTrue(exports.list(otherCreator,101,null,null).stream().noneMatch(j->j.id().equals(first.id())));var member=platform.membership(admin,OTHER).orElseThrow();var foreign=new AssetExportJobRepository.Access(admin,OTHER,member.permissionVersion(),UUID.randomUUID().toString());assertEquals(404,assertThrows(DomainException.class,()->exports.get(foreign,first.id())).status);}
    @Test void staleMembershipRejectsReadsAndEvenAnExistingReplayReceipt()throws Exception{var a=access(admin);var f=filter();String key=UUID.randomUUID().toString();var first=accept(a,f,key);var before=counts();var stale=new AssetExportJobRepository.Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->exports.get(stale,first.id())).status);assertEquals(401,assertThrows(DomainException.class,()->platform.idempotentAuthorized(stale.actorId(),stale.tenantId(),ROUTE,key,hash(a,f),stale.permissionVersion(),()->exports.authorizeAcceptance(stale),()->exports.accept(stale,f))).status);assertEquals(before,counts());}
    @Test void missingMembershipCannotReadUnknownJob(){var a=new AssetExportJobRepository.Access(UUID.randomUUID().toString(),TENANT,1,"synthetic");assertEquals(401,assertThrows(DomainException.class,()->exports.get(a,UUID.randomUUID().toString())).status);}
    @Test void writesOutsideProtectedIdempotentScopeAreRejected()throws Exception{var before=counts();var a=access(admin);assertThrows(IllegalStateException.class,()->exports.authorizeAcceptance(a));assertThrows(IllegalStateException.class,()->exports.accept(a,filter()));assertEquals(before,counts());}
    @Test void rollbackAfterAcceptanceRemovesJobAuditAndReceiptTogether()throws Exception{var before=counts();var a=access(admin);var f=filter();assertThrows(IllegalStateException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,UUID.randomUUID().toString(),hash(a,f),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->{exports.accept(a,f);throw new IllegalStateException("SYNTHETIC_ROLLBACK");}));assertEquals(before,counts());}
    @Test void boundedCursorPagesKeepStableCreationIdOrderAndImmutableResults(){var a=access(admin);for(int i=0;i<3;i++)accept(a,filter(),UUID.randomUUID().toString());var all=exports.list(a,101,null,null);var paged=new ArrayList<Job>();Instant time=null;String id=null;for(int i=0;i<all.size();i++){var page=exports.list(a,1,time,id);assertEquals(1,page.size());var j=page.get(0);paged.add(j);time=j.createdAt();id=j.id();}assertEquals(all,paged);assertThrows(UnsupportedOperationException.class,all::clear);}
    @Test void invalidPaginationAndTraceFailWithoutAcceptingOrReadingRows()throws Exception{var a=access(admin);for(int limit:new int[]{0,102})assertEquals(400,assertThrows(DomainException.class,()->exports.list(a,limit,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->exports.list(a,15,Instant.EPOCH,null)).status);assertEquals(400,assertThrows(DomainException.class,()->exports.list(a,15,Instant.EPOCH.plusNanos(1),UUID.randomUUID().toString())).status);var bad=new AssetExportJobRepository.Access(a.actorId(),a.tenantId(),a.permissionVersion(),"invalid trace");var before=counts();assertEquals(400,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->exports.authorizeAcceptance(bad),()->exports.accept(bad,filter()))).status);assertEquals(before,counts());}
    @Test void nullFiltersCannotBecomeAnUnboundedDefaultAcceptance()throws Exception{var before=counts();var a=access(admin);assertEquals(400,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->exports.accept(a,null))).status);assertEquals(before,counts());}
    @Test void readbackNeverReturnsStoredCommandOrPreparedFileBytes()throws Exception{var a=access(admin);var job=accept(a,filter(),UUID.randomUUID().toString());var before=counts();var value=mapper.valueToTree(exports.get(a,job.id()));for(String field:List.of("command_bytes","file_bytes","object_id","signed_url","download_url","trace_id"))assertFalse(value.has(field));assertEquals(before,counts());}
    @Test void concurrentSameKeyAcceptanceHasOneCommitAndOneOriginalReceipt()throws Exception{var a=access(admin);var f=filter();String key=UUID.randomUUID().toString();var before=counts();var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var go=new CountDownLatch(1);try{Callable<Job> action=()->{ready.countDown();assertTrue(go.await(5,TimeUnit.SECONDS));return accept(a,f,key);};var one=executor.submit(action);var two=executor.submit(action);assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();assertEquals(one.get(10,TimeUnit.SECONDS),two.get(10,TimeUnit.SECONDS));}finally{executor.shutdownNow();}assertEquals(List.of(before.get(0)+1,before.get(1),before.get(2)+1,before.get(3)+1),counts());}
    @Test void nestedReadCannotSplitAnExistingWriteTransaction()throws Exception{var before=counts();var a=access(admin);assertThrows(IllegalStateException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->exports.list(a,15,null,null)));assertEquals(before,counts());}
    @Test void auditFailureRollsBackJobAndOriginalReceipt()throws Exception{fault(true,null);}
    @Test void malformedCanonicalBytesNeverEscapeAsSuccessfulAcceptance()throws Exception{fault(false,new byte[]{1,2,3});}
    @Test void validForeignCanonicalBodyCannotChooseItsOwnScope()throws Exception{var original=access(admin);byte[] foreign=new Command(new AssetExportJobState.Access(UUID.fromString(OTHER),UUID.fromString(admin),original.permissionVersion(),"padmin",true),filter()).canonicalBytes();fault(false,foreign);}
    static void fault(boolean auditFailure,byte[] replacement)throws Exception{
        DataSource injected=(DataSource)java.lang.reflect.Proxy.newProxyInstance(PostgresAssetExportRepositoryIntegrationTest.class.getClassLoader(),new Class[]{DataSource.class},(proxy,method,args)->{
            if(method.getName().equals("getConnection")){Connection real=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(PostgresAssetExportRepositoryIntegrationTest.class.getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{
                if(cm.getName().equals("prepareStatement")&&ca[0] instanceof String sql){
                    if(auditFailure&&sql.startsWith("INSERT INTO public.mop_audit"))throw new SQLException("SYNTHETIC_AUDIT_FAILURE_NOT_SECRET","22012");
                    if(replacement!=null&&sql.startsWith("INSERT INTO public.mop_asset_export_job")){
                        PreparedStatement realStatement=(PreparedStatement)cm.invoke(real,ca);
                        return java.lang.reflect.Proxy.newProxyInstance(PostgresAssetExportRepositoryIntegrationTest.class.getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{
                            if(sm.getName().equals("setBytes")&&Integer.valueOf(6).equals(sa[0]))sa=new Object[]{6,replacement.clone()};
                            try{return sm.invoke(realStatement,sa);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
                        });
                    }
                }
                try{return cm.invoke(real,ca);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
            });}
            try{return method.invoke(pool,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
        });
        var scopedPlatform=new PostgresPlatformRepository(injected,mapper);var scopedExports=new PostgresAssetExportRepository(injected,scopedPlatform);var before=counts();var a=access(admin);var f=filter();
        var error=assertThrows(DomainException.class,()->scopedPlatform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,UUID.randomUUID().toString(),hash(a,f),a.permissionVersion(),()->scopedExports.authorizeAcceptance(a),()->scopedExports.accept(a,f)));
        assertEquals(503,error.status);assertFalse(error.getMessage().contains("SYNTHETIC"));assertEquals(before,counts());
    }

}
